INSERT OR REPLACE INTO books (name, registered, status, horizon, universe, direction, entry, stop, exit_rule, kill_criterion, doc, notes) VALUES ('Range v3 mid-target', '2026-10-19', 'running', '15m bars, median hold ~1h, 48-bar cap', 'registered 27 (same as Range v2.2)', 'both', 'identical to Range v2.2: containment switch > frozen median, ladder 15/25/30/30% at +0.30/+0.05/-0.25/-0.55 ATR, chase fills, 6h cooldown', 'identical to v2.2: close beyond the band by 1.5 ATR, switch off, or 48 bars', 'ONE target: every lot exits at the mid EMA (v2.2 scales out 40% mid / 40% band / 20% band+0.35)', 'judged against v2.2 on the same days: PASS if v3 minus v2.2 > 0 at 300 trips each; voids if either book changes', '91', 'finding 161: single mid target +0.207%/ep t=63 vs v2.2 +0.108% t=18 over 5y; 100% coins, 100% months; live-window overlay 16-19 Oct +0.028% vs -0.014%. Single lot at the band LOSES (-0.108%) - the adds at worse prices are the edge. src/paperbook6.py, runs/paper6_state.json');
INSERT OR REPLACE INTO findings(doc,title,verdict,summary,date) VALUES ('161','Range book ladder shape and target (scale-in test from the /CL room geometry)','PROMISING','One target at the mid EMA beats the three-step scale-out on the range book: +0.207%/ep t=63, 72% win, median +0.49%, hold ~1h, 100% coins, 100% months, maxDD -9% vs v2.2 +0.108% t=18. Robust to lot shape (every mid-target ladder >= +0.14%). Single lot at the band with no adds loses -0.108% and blows up: the adds at worse prices ARE the edge (with doc 65, doc 73, his /CL algo). Registered as Range v3 paper book beside v2.2. Doc 91.','2026-10-19');
INSERT OR REPLACE INTO rules(id,rule,source,date) VALUES (167,'On mean-reversion books the exit is one target at the mean; scale-out exits belong to trend books. A single lot with no adds is not the range book - never test the entry without its ladder','doc 91','2026-10-19');
