INSERT OR REPLACE INTO books (name, registered, status, horizon, universe, direction, entry, stop, exit_rule, kill_criterion, doc, notes) VALUES ('Ignition v1 (NQ)', '2026-10-19', 'running', '5-min bars, median hold ~30 min, 3h cap', 'Nasdaq-100 (Dukascopy USATECHIDXUSD CFD ticks)', 'both', 'bar range >= 1.25x avg of prior 20; |tick-rule delta|/ticks >= 0.05 with sign; EMA20 vs EMA50 alignment; candle agrees. Governors: 8/day, 3-bar cooloff, 200-pt daily cap', '45 pts hard; breakeven at +15; trail 1 ATR(20); target 9 ATR', 'stop / breakeven / trail / target / 36-bar cap; 1 MNQ-equivalent, $2/pt', 'REAL minus SHADOW (5 random completed bars, same side, same stack) > 0 at 300 trades; early kill any 50-trade block < -150 pts', '92', 'AuclairsDad engine from his own blueprint (docs 90, 92). 12-month study: +3.60 pts/tr, PF 1.32, 74% win, t 2.6, 694 trades, both halves +, 11/13 months; replay from 2025-10-15 $2,000 -> $6,994, maxDD -31%. Full replay from start each day (anti-leak). src/paperbook7.py, runs/paper7_state.json, data_nq_cache/nq_5m.csv');
UPDATE findings SET verdict='PROMISING', summary='AuclairsDad engine from his blueprint on 12 months of NQ 5-min: ignition + delta share + HTF alignment (no coil) +3.60 pts/trade, PF 1.32, 74% win, t 2.6, 694 trades, both halves positive, 11/13 months; counter-HTF loses, no-HTF random. Same engine = random on crypto. Registered as paper book Ignition v1 (paperbook7). Doc 92.' WHERE doc='157';
INSERT OR REPLACE INTO rules(id,rule,source,date) VALUES (168,'When an imported engine has several gates, run the ablation table on the full sample before choosing the registered form; register the row that held in both halves, not the one matching the source screenshot','doc 92','2026-10-19');
